onload
VAR_TEMP_0 0 BattleFrontier_BattleFactoryBattleRoom_EventScript_EnterRoom
movements
BattleFrontier_BattleFactoryBattleRoom_Movement_NolandMoveToBattle	up,up,up,face_left,end
